mapper.select:
SELECT 

WHERE l.student_id = #{studentId} AND l.deleted = 0
AND l.status = #{status}
ORDER BY l.created_at DESC, l.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM leave_request l
WHERE l.student_id = #{studentId} AND l.deleted = 0
AND l.status = #{status}

SELECT 

WHERE l.deleted = 0
AND l.status = #{status}
AND sp.counselor_id = #{scopeCounselorId}

    AND (u.real_name LIKE CONCAT('%', #{keyword}, '%')
         OR u.username LIKE CONCAT('%', #{keyword}, '%')
         OR sp.student_no LIKE CONCAT('%', #{keyword}, '%')
         OR sp.class_name LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY FIELD(l.status, 'pending') DESC, l.created_at DESC, l.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT 

WHERE l.deleted = 0 AND l.status = 'approved' AND l.end_at < #{before}
AND sp.counselor_id = #{scopeCounselorId}
ORDER BY l.end_at ASC, l.id ASC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM leave_request l
LEFT JOIN student_profile sp ON sp.user_id = l.student_id AND sp.deleted = 0
WHERE l.deleted = 0 AND l.status = 'approved' AND l.end_at < #{before}
AND sp.counselor_id = #{scopeCounselorId}
